// ── ClaimFlow PII crypto ──────────────────────────────────────────
// Single source of truth for field-level encryption. Used by:
//   * the Encrypt_PII_Func Code node (this source is copied into the workflow)
//   * scripts/encrypt-seed-pii.js (require()d directly)
// Format: v1:<iv b64>:<auth tag b64>:<ciphertext b64>   (AES-256-GCM)
// The field name ("name" | "email" | "phone") is bound as associated data, so a
// ciphertext moved to a different column will not decrypt. See docs/security.md.
const crypto = require('crypto');

function piiKeys(env) {
  const key = Buffer.from(String(env.CLAIMFLOW_PII_KEY || ''), 'base64');
  const hmacKey = Buffer.from(String(env.CLAIMFLOW_PII_HMAC_KEY || ''), 'base64');
  if (key.length !== 32) throw new Error('CLAIMFLOW_PII_KEY must be 32 random bytes, base64-encoded');
  if (hmacKey.length !== 32) throw new Error('CLAIMFLOW_PII_HMAC_KEY must be 32 random bytes, base64-encoded');
  if (key.equals(hmacKey)) throw new Error('CLAIMFLOW_PII_KEY and CLAIMFLOW_PII_HMAC_KEY must differ');
  return { v1: key, hmacKey };
}

function encryptField(value, field, keys) {
  if (value === null || value === undefined || String(value).trim() === '') return null;
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', keys.v1, iv);
  cipher.setAAD(Buffer.from(field, 'utf8'));
  const ct = Buffer.concat([cipher.update(String(value), 'utf8'), cipher.final()]);
  return ['v1', iv.toString('base64'), cipher.getAuthTag().toString('base64'), ct.toString('base64')].join(':');
}

function decryptField(token, field, keys) {
  if (token === null || token === undefined) return null;
  const [version, iv, tag, ct] = String(token).split(':');
  const key = keys[version];
  if (!key || !iv || !tag || ct === undefined) throw new Error(`Unsupported or malformed ciphertext (${version})`);
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, Buffer.from(iv, 'base64'));
  decipher.setAAD(Buffer.from(field, 'utf8'));
  decipher.setAuthTag(Buffer.from(tag, 'base64'));
  return Buffer.concat([decipher.update(Buffer.from(ct, 'base64')), decipher.final()]).toString('utf8');
}

// Deterministic, non-reversible lookup key for exact-match email searches.
function blindIndex(email, keys) {
  return crypto.createHmac('sha256', keys.hmacKey).update(String(email).trim().toLowerCase(), 'utf8').digest('hex');
}

// ── Render claimant email ────────────────────────────────────────
// Decrypts name/email IN MEMORY only, picks a template, escapes every inserted value,
// and returns HTML + plain text. Claimants never see scores, flags or the word "fraud".
const keys = piiKeys($env);
const input = $('Notify_Trigger').first().json;       // { claim_ref, template, message }
const row = $input.first().json;                      // claim row (null columns if not found)
if (!row.claim_ref) throw new Error(`Notification: claim ${input.claim_ref} not found`);

const name = decryptField(row.claimant_name_enc, 'name', keys) || 'there';
const email = decryptField(row.claimant_email_enc, 'email', keys);
if (!email) throw new Error(`Notification: claim ${row.claim_ref} has no email address`);

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const first = String(name).trim().split(/\s+/)[0];
const money = (n) => 'R ' + Number(n).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const statusUrl = `${$env.WEBHOOK_URL}webhook/claims/status?ref=${encodeURIComponent(row.claim_ref)}`;
const mask = (addr) => { const [u, d] = String(addr).split('@'); return `${u.slice(0, 1)}${'*'.repeat(Math.max(u.length - 1, 3))}@${d}`; };

const REASON_TEXT = {
  policy_not_found: 'We could not find an Acme Cover policy with the policy number you gave us.',
  policy_not_active: 'The policy was not active on the date of the incident.',
  incident_outside_cover: "The incident date falls outside the policy's period of cover.",
  amount_exceeds_sum_insured: 'The amount claimed is more than the sum insured on the policy.',
};
const reasons = (row.rejection_reasons || []).map((r) => REASON_TEXT[r] || 'The claim does not meet the policy conditions.');
const reviewerMessage = String(input.message || '').trim();

// Each template: subject, paragraphs (plain text; escaped when rendered), optional list
const T = {
  received: {
    subject: `We've received your claim ${row.claim_ref}`,
    paras: [
      `Thank you for submitting your claim. Your claim reference is ${row.claim_ref}.`,
      'A member of our claims team will review it and contact you if we need anything else. Please keep your reference number handy.',
    ],
  },
  approved_for_assessment: {
    subject: `Your claim ${row.claim_ref} has been approved for assessment`,
    paras: [
      'Good news: your claim has been approved for assessment. An assessor will contact you within 2 working days to arrange the next steps.',
      'To help things move quickly, please have photos of the damage and any quotes or invoices ready.',
    ],
  },
  rejected_ineligible: {
    subject: `Update on your claim ${row.claim_ref}`,
    paras: [
      "Unfortunately we can't accept this claim under the policy, for the following reason(s):",
    ],
    list: reasons.length ? reasons : ['The claim does not meet the policy conditions.'],
    after: ['If you think this is a mistake, reply to this email with your policy documents and we will look at it again.'],
  },
  rejected: {
    subject: `Update on your claim ${row.claim_ref}`,
    paras: [
      'After reviewing your claim, we are unable to proceed with it.',
      'If you would like us to reconsider, reply to this email within 30 days with any additional information or documents and a senior claims handler will review it.',
    ],
  },
  more_info_required: {
    subject: `We need more information about your claim ${row.claim_ref}`,
    paras: reviewerMessage
      ? ['To continue with your claim, we need some more information:', reviewerMessage, 'Please reply to this email with the details or documents requested.']
      : ['To continue with your claim, we need some more information. Please reply to this email with photos of the damage, any police case number, and quotes or invoices.'],
  },
};
const t = T[input.template];
if (!t) throw new Error(`Notification: unknown template "${input.template}"`);

const details = [
  ['Claim reference', row.claim_ref],
  ['Product', row.product ? row.product.charAt(0).toUpperCase() + row.product.slice(1) : 'n/a'],
  ['Incident date', row.incident_date],
  ['Amount claimed', money(row.claimed_amount)],
];

// ── HTML (inline styles: email clients ignore stylesheets) ──
const p = (s) => `<p style="margin:0 0 14px;font-size:15px;line-height:1.55;color:#1f2933;">${esc(s)}</p>`;
const html = `<!DOCTYPE html><html><body style="margin:0;padding:0;background:#f3f5f7;font-family:Arial,Helvetica,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f5f7;padding:24px 0;"><tr><td align="center">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border-radius:8px;overflow:hidden;">
<tr><td style="background:#0b4f6c;padding:20px 28px;color:#ffffff;font-size:20px;font-weight:bold;">Acme Cover</td></tr>
<tr><td style="padding:28px;">
${p(`Hi ${first},`)}
${t.paras.map(p).join('\n')}
${t.list ? `<ul style="margin:0 0 14px 18px;padding:0;">${t.list.map((li) => `<li style="font-size:15px;line-height:1.55;color:#1f2933;">${esc(li)}</li>`).join('')}</ul>` : ''}
${(t.after || []).map(p).join('\n')}
<table role="presentation" cellpadding="0" cellspacing="0" style="margin:8px 0 20px;background:#f3f5f7;border-radius:6px;width:100%;">
${details.map(([k, v]) => `<tr><td style="padding:8px 14px;font-size:13px;color:#52606d;width:40%;">${esc(k)}</td><td style="padding:8px 14px;font-size:13px;color:#1f2933;font-weight:bold;">${esc(v)}</td></tr>`).join('')}
</table>
<a href="${esc(statusUrl)}" style="display:inline-block;background:#0b4f6c;color:#ffffff;text-decoration:none;padding:12px 20px;border-radius:6px;font-size:14px;">Check claim status</a>
${p('')}
${p('Kind regards,')}
<p style="margin:0;font-size:15px;color:#1f2933;">Acme Cover Claims</p>
</td></tr>
<tr><td style="padding:16px 28px;background:#f8fafc;font-size:11px;color:#7b8794;">Acme Cover is a fictional insurer used in a portfolio demo. Please do not reply with real personal information.</td></tr>
</table></td></tr></table></body></html>`;

// ── Plain-text alternative ──
const text = [
  `Hi ${first},`, '',
  ...t.paras.flatMap((s) => [s, '']),
  ...(t.list ? [...t.list.map((li) => `- ${li}`), ''] : []),
  ...(t.after || []).flatMap((s) => [s, '']),
  ...details.map(([k, v]) => `${k}: ${v}`), '',
  `Check claim status: ${statusUrl}`, '',
  'Kind regards,', 'Acme Cover Claims',
].join('\n');

return [{
  json: {
    claim_ref: row.claim_ref,
    template: input.template,
    to: email,
    to_masked: mask(email),
    subject: t.subject,
    html,
    text,
  },
}];

parameters.query:
INSERT INTO claim_events (claim_ref, event_type, actor, detail)
VALUES ($1, 'notification_sent', 'system', jsonb_build_object('template', $2::text, 'to', $3::text))
RETURNING id;
